  test('2. Figure 12.15 — Sample Official Match Box Score (Finalized Championship Match)', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 1180 });
    await configureSessionAndTheme(page, 'admin');

    // First, capture the MatchBoxScoreModal on /athletics -> MATCHES tab -> CEAT Red Scorpions 92 vs 88 CS Byte Titans
    await page.goto('/athletics');
    await waitForContentReady(page, 1800);

    // Click the MATCHES tab in Athletics Hub
    const matchesTabBtn = page.locator('button[role="tab"]', { hasText: /MATCHES/i }).first();
    await matchesTabBtn.click({ force: true });
    await page.waitForTimeout(1000);

    // Type "CEAT Red Scorpions" or click the 92 VS 88 Finals match card
    const searchInput = page.getByPlaceholder(/Search players, coaches, teams, matches/i);
    if (await searchInput.isVisible().catch(() => false)) {
      await searchInput.fill('Basketball Championship (Marquee)');
      await page.waitForTimeout(600);
    }

    const finalsCard = page.locator('div, button', { hasText: /92/ }).filter({ hasText: /88/ }).first();
    await finalsCard.click({ force: true });
    await page.waitForTimeout(1800);

    // Expand the MatchBoxScoreModal dialog height so Scoreboard Banner, Dual Team Box Score Tables (with 3PM, 2PM, FTM, PTS & Red ★ MVP badge), Play-by-Play Timeline, and Official Scorer Certification Audit are all visible without internal scroll clipping
    await page.evaluate(() => {
      const dialog = document.querySelector('[role="dialog"]') as HTMLElement | null;
      if (dialog) {
        dialog.style.maxHeight = '96vh';
        dialog.style.maxWidth = '1040px';
        const scrollArea = dialog.querySelector('.overflow-y-auto') as HTMLElement | null;
        if (scrollArea) {
          scrollArea.style.maxHeight = 'none';
          scrollArea.style.overflow = 'visible';
        }
        dialog.querySelectorAll('.max-h-48').forEach((el) => {
          (el as HTMLElement).style.maxHeight = '105px';
        });
        // Format any lowercase test athlete label in the box score table
        dialog.querySelectorAll('td span, td button').forEach((el) => {
          if (el.textContent?.trim() === 'juan') {
            el.textContent = 'Juan Miguel Santos (CEAT)';
          }
        });
      }
    });
    await page.waitForTimeout(500);

    await page.screenshot({
      path: path.join(OUT_DIR, 'figure-12-15-official-match-box-score.png'),
      fullPage: false,
    });

    // Also capture 12.15b: The finalized Match Console (/match/b2561fce-6d3b-47fa-b68c-9edda34cadca) scrolled to frame the Final Scoreboard + Official Red Star MVP Recognition + Match Box Score & Scorers card together
    await page.setViewportSize({ width: 1440, height: 1240 });
    await page.goto('/match/b2561fce-6d3b-47fa-b68c-9edda34cadca');
    await waitForContentReady(page, 1800);

    await page.evaluate(() => {
      window.scrollTo({ top: 410, behavior: 'instant' });
    });
    await page.waitForTimeout(500);

    await page.screenshot({
      path: path.join(OUT_DIR, 'figure-12-15b-match-console-red-star-mvp-record.png'),
      fullPage: false,
    });
  });

