  test('4. Figure 12.17 — Sample Generated Tournament Bracket Record', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 1150 });
    await configureSessionAndTheme(page, 'admin');

    await page.goto('/explorer');
    await waitForContentReady(page, 1800);

    // 1. Click the BASKETBALL sport discipline pill
    const basketballSportBtn = page.locator('button', { hasText: /BASKETBALL/i }).first();
    if (await basketballSportBtn.isVisible().catch(() => false)) {
      await basketballSportBtn.click({ force: true });
      await page.waitForTimeout(800);
    }

    // 2. Click Phase 2: Playoff Bracket tab button (aria-label="Phase 2 Playoff Bracket")
    const playoffTabBtn = page.locator('button[aria-label="Phase 2 Playoff Bracket"]');
    await playoffTabBtn.click({ force: true });
    await page.waitForTimeout(1000);

    // 3. Select the completed "PSU Binturungan 2026 - Basketball Championship (Marquee)" bracket pill if multiple exist
    const marqueeBtn = page.locator('button', { hasText: /Basketball Championship \(Marquee\)/i }).first();
    if (await marqueeBtn.isVisible().catch(() => false)) {
      await marqueeBtn.click({ force: true });
      await page.waitForTimeout(800);
    }

    // 4. Scroll so the Official Collegiate Champion banner + Knockout Bracket Tree (Quarter-Finals -> Semi-Finals -> Championship Final + 3rd Place Playoff) are framed together with full Crown icon visible
    await page.evaluate(() => {
      const champBanner = Array.from(document.querySelectorAll('span, h2, h3')).find(
        (el) =>
          el.textContent?.includes('Official Collegiate Champion') ||
          el.textContent?.includes('Official Binturungan Tribe Champion')
      );
      if (champBanner) {
        const rect = champBanner.getBoundingClientRect();
        window.scrollTo({ top: Math.max(0, window.scrollY + rect.top - 85), behavior: 'instant' });
      } else {
        window.scrollTo({ top: 340, behavior: 'instant' });
      }
    });
    await page.waitForTimeout(600);

    await page.screenshot({
      path: path.join(OUT_DIR, 'figure-12-17-automated-tournament-bracket-output.png'),
      fullPage: false,
    });
  });
